use super::*;
use semio_framework_value::{DslValue,retained_clone::RetainedCloneSource,retirement::controlled::ControlledRetirement};
fn observed<R>(f:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(f)}
struct Wallet{stock:RetainedCloneGrant,fuel:u64}
impl Wallet{fn new(f:&serde_json::Value)->Self{Self{stock:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:f["fuel"].as_u64().unwrap()}}fn loan(&self,d:RetirementDemand)->RetainedCloneGrant{assert!(self.fuel>0&&semio_framework_value::retained_clone::retained_clone_grant_admits(self.stock,d));RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}fn post(&mut self,p:RetainedCloneProgress,work:u64,heap:(usize,usize)){assert!(p.fits(self.stock));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.stock.maximum_items-=p.copied_items;self.stock.maximum_copy_bytes-=p.copied_bytes;self.stock.maximum_capacity_bytes-=p.retained_capacity_bytes;self.stock.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();}}
#[test]fn actual_expanded_paths_sort_and_duplicate_retirement_keep_one_finite_owner_wallet(){let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();for case in f["cases"].as_array().unwrap(){let input:Vec<String>=serde_json::from_value(case["input"].clone()).unwrap();let oracle=input.iter().cloned().collect::<std::collections::BTreeSet<_>>().into_iter().collect::<Vec<_>>();assert_eq!(serde_json::to_value(&oracle).unwrap(),case["expected"]);for cut in f["cancelCuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap())).chain([None]){let mut bank=Wallet::new(&f["stock"]);let original=DslValue::Array(input.iter().cloned().map(DslValue::String).collect());let g=RetainedCloneGrant{maximum_items:1,..bank.stock};let(turn,heap)=observed(||RetainedCloneSource::admit_owned(original,(),g));let work=turn.work;let(mut source,p)=turn.result.map_err(|(e,..)|e).unwrap();bank.post(p,work,heap);let(mut receiver,heap)=observed(||<DagExpandedPaths as NativeReceive<DslValue>>::receiver());assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);for index in 0..f["stock"]["maximumTurns"].as_u64().unwrap(){if cut==Some(index)||receiver.output_ready(){break}let d=receiver.demands(source.borrow(),4096).unwrap();let g=bank.loan(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(turn,heap)=observed(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source.borrow(),4096).unwrap(),d);}let(turn,heap)=observed(||receiver.advance(source.borrow(),&mut control,4096,g));let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,heap);turn.result.unwrap();}
 if cut.is_none(){assert!(receiver.output_ready());let g=bank.loan(receiver.take_demand().unwrap());let(turn,heap)=observed(||receiver.take(RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));let(turn,heap)=observed(||receiver.take(g));let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,0);bank.post(p,work,heap);assert_eq!(output.iter().collect::<Vec<_>>(),oracle.iter().collect::<Vec<_>>());let mut close=ControlledRetirement::new(output).map_err(|(e,_)|e).unwrap();for _ in 0..f["stock"]["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let g=bank.loan(close.next_demand(4096).unwrap());let(result,heap)=observed(||close.step(g));let work=close.last_turn_work();let p=match&result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,work,heap);result.unwrap();}assert!(close.terminal_is_empty());}
 receiver.begin_close();for _ in 0..f["stock"]["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty(){break}let g=bank.loan(receiver.close_demands(4096).unwrap());let(turn,heap)=observed(||receiver.close_step(g));let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,heap);turn.result.unwrap();}assert!(receiver.terminal_is_empty());assert_eq!(observed(||drop(receiver)).1,(0,0));for _ in 0..f["stock"]["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}let g=bank.loan(source.next_close_demand(4096).unwrap());let(turn,heap)=observed(||source.close_step(g));let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};bank.post(p,turn.work,heap);turn.result.unwrap();}assert!(source.terminal_is_empty());}}}
